// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    Recorder rec;

    function setUp() public { c = new SimpleWallet(); rec = new Recorder(); }

    function testFuzz_property(uint256 deposit, uint256 amount) public {
        vm.assume(deposit <= VALUE_CAP);
        deposit = bound(deposit, 1 ether, 100 ether);
        amount = bound(amount, 0, deposit - 1);
        vm.deal(address(this), deposit);
        (bool okFund,) = address(c).call{value: deposit}("");
        assertTrue(okFund);
        c.sendMoney(address(rec), amount, "");
        assertEq(rec.lastValue(), amount);
    }
}

contract Recorder {
    uint256 public lastValue;
    receive() external payable { lastValue = msg.value; }
}
